function cmVideoMeta(file) {
  return new Promise((res) => {
    try {
      const url = URL.createObjectURL(file);
      const v = document.createElement("video");
      v.preload = "metadata";
      v.onloadedmetadata = () => {
        URL.revokeObjectURL(url);
        res({ duration: v.duration || 0 });
      };
      v.onerror = () => {
        URL.revokeObjectURL(url);
        res({ duration: 0 });
      };
      v.src = url;
    } catch (_) {
      res({ duration: 0 });
    }
  });
}
